class Program {
public static void swap(ref int x, ref int y) {

int temp = x;
x = y;
y = temp;
} p
ublic static void Main (string[] args) {
int a = 5, b = 10;
swap (ref a, ref b);
// a = 10, b = 5;
Console.WriteLine ("a = {0}, b = {1}", a, b);
}
}
}
