// 写锁，数据条数
final ReentrantLock putLock = this.putLock;
final AtomicInteger count = this.count;
// 允许中断的加锁方式
putLock.lockInterruptibly();
try {
// 如果元素个数和限制个数一致，直接准备挂起
while (count.get() == capacity) {
// 挂起的时间是不是已经没了
if (nanos <= 0)
// 添加失败，返回false
return false;
// 挂起线程
nanos = notFull.awaitNanos(nanos);
}
// 有空余位置，enqueue添加数据
enqueue(new Node<E>(e));
// 元素个数 + 1
c = count.getAndIncrement();
// 当前添加完数据，还有位置可以添加数据，唤醒可能阻塞的生产者
if (c + 1 < capacity)
notFull.signal();
} finally {
// 释放锁
putLock.unlock();
}
// 如果之前元素个数是0，唤醒可能等待的消费者
if (c == 0)
signalNotEmpty();
return true;
}

public void put(E e) throws InterruptedException {
if (e == null) throw new NullPointerException();
int c = -1;
Node<E> node = new Node<E>(e);
final ReentrantLock putLock = this.putLock;
final AtomicInteger count = this.count;
putLock.lockInterruptibly();
try {
while (count.get() == capacity) {
// 一直挂起线程，等待被唤醒
notFull.await();
}
enqueue(node);
c = count.getAndIncrement();
if (c + 1 < capacity)
notFull.signal();
} finally {
putLock.unlock();
}
if (c == 0)
signalNotEmpty();
}

// 数组的初始长度
private static final int DEFAULT_INITIAL_CAPACITY = 11;
// 数组的最大长度
// -8的目的是为了适配各个版本的虚拟机
// 默认当前使用的hotspot虚拟机最大支持Integer.MAX_VALUE - 2，但是其他版本的虚拟机不一定。
private static final int MAX_ARRAY_SIZE = Integer.MAX_VALUE - 8;
// 存储数据的数组，也是基于这个数组实现的二叉堆。
private transient Object[] queue;
// size记录当前阻塞队列中元素的个数
private transient int size;
// 要求使用的对象要实现Comparable比较器。基于comparator做对象之间的比较
private transient Comparator<? super E> comparator;
// 实现阻塞队列的lock锁
private final ReentrantLock lock;
// 挂起线程操作。
private final Condition notEmpty;
// 因为PriorityBlockingQueue的底层是基于二叉堆的，而二叉堆又是基于数组实现的，数组长度是固定的，如果需要扩容，需要构建一个新数组。PriorityBlockingQueue在做扩容操作时，不会lock住的，释放lock锁，基于allocationSpinLock属性做标记，来避免出现并发扩容的问题。
private transient volatile int allocationSpinLock;
// 阻塞队列中用到的原理，其实就是普通的优先级队列。
private PriorityQueue<E> q;

因为add方法依然调用的是offer方法，直接查看offer方法即可
public boolean offer(E e) {
// 非空判断。
if (e == null)
throw new NullPointerException();
// 拿到锁，直接上锁
final ReentrantLock lock = this.lock;
lock.lock();
// n：size，元素的个数
// cap：当前数组的长度
// array：就是存储数据的数组
int n, cap;
Object[] array;
while ((n = size) >= (cap = (array = queue).length))
// 如果元素个数大于等于数组的长度，需要尝试扩容。
tryGrow(array, cap);
try {
// 拿到了比较器
Comparator<? super E> cmp = comparator;
// 比较数据大小，存储数据，是否需要做上移操作，保证平衡的
if (cmp == null)
siftUpComparable(n, e, array);
else
siftUpUsingComparator(n, e, array, cmp);
// 元素个数 + 1
size = n + 1;
// 如果有挂起的线程，需要去唤醒挂起的消费者。
notEmpty.signal();
} finally {
// 释放锁
lock.unlock();
}
// 返回true
return true;
}

在添加数据之前，会采用while循环的方式，来判断当前元素个数是否大于等于数组长度。如果满
足，需要执行tryGrow方法，对数组进行扩容
如果两个线程同时执行tryGrow，只会有一个线程在扩容，另一个线程可能多次走while循环，多次
走tryGrow方法，但是依然需要等待前面的线程扩容完毕。
private void tryGrow(Object[] array, int oldCap) {
// 释放锁资源。
lock.unlock();
// 声明新数组。
Object[] newArray = null;
// 如果allocationSpinLock属性值为0，说明当前没有线程正在扩容的。
if (allocationSpinLock == 0 &&
// 基于CAS的方式，将allocationSpinLock从0修改为1，代表当前线程可以开始扩容
UNSAFE.compareAndSwapInt(this, allocationSpinLockOffset,0, 1)) {
try {
// 计算新数组长度
int newCap = oldCap + ((oldCap < 64) ?
// 如果数组长度比较小，这里加快扩容长度速度。
(oldCap + 2) :
// 如果长度大于等于64了，每次扩容到1.5倍即可。
(oldCap >> 1));
// 如果新数组长度大于MAX_ARRAY_SIZE，需要做点事了。
if (newCap - MAX_ARRAY_SIZE > 0) {
// 声明minCap，长度为老数组 + 1
int minCap = oldCap + 1;
// 老数组+1变为负数，或者老数组长度已经大于MAX_ARRAY_SIZE了，无法扩容了。
if (minCap < 0 || minCap > MAX_ARRAY_SIZE)
// 告辞，凉凉~~~~
throw new OutOfMemoryError();
// 如果没有超过限制，直接设置为最大长度即可
newCap = MAX_ARRAY_SIZE;
}
// 新数组长度，得大于老数组长度，
// 第二个判断确保没有并发扩容的出现。
if (newCap > oldCap && queue == array)
// 构建出新数组
newArray = new Object[newCap];
} finally {
// 新数组有了，标记位归0~~
allocationSpinLock = 0;
}
}
// 如果到了这，newArray依然为null，说明这个线程没有进到if方法中，去构建新数组
if (newArray == null)
// 稍微等一手。
Thread.yield();
// 拿锁资源，
lock.lock();
// 拿到锁资源后，确认是构建了新数组的线程，这里就需要将新数组复制给queue，并且导入数据
if (newArray != null && queue == array) {
// 将新数组赋值给queue
queue = newArray;
// 将老数组的数据全部导入到新数组中。
System.arraycopy(array, 0, newArray, 0, oldCap);
}
}

这里是数据如何放到数组上，并且如何保证的二叉堆结构
// k：当前元素的个数（其实就是要放的索引位置）
// x：需要添加的数据
// array：数组。。
private static <T> void siftUpComparable(int k, T x, Object[] array) {
// 将插入的元素直接强转为Comparable（com.mashibing.User cannot be cast to java.lang.Comparable）
// 这行强转，会导致添加没有实现Comparable的元素，直接报错。
Comparable<? super T> key = (Comparable<? super T>) x;
// k大于0，走while逻辑。（原来有数据）
while (k > 0) {
// 获取父节点的索引位置。
int parent = (k - 1) >>> 1;
// 拿到父节点的元素。
Object e = array[parent];
// 用子节点compareTo父节点，如果 >= 0，说明当前son节点比parent要大。
if (key.compareTo((T) e) >= 0)
// 直接break，完事，
break;
// 将son节点的位置设置上之前的parent节点
array[k] = e;
// 重新设置x节点需要放置的位置。
k = parent;
}
// k == 0，当前元素是第一个元素，直接插入进去。
array[k] = key;
}

