});
new Thread(() -> {
System.out.println("Tom到位！！！");
try {
barrier.await();
} catch (Exception e) {
System.out.println("悲剧，人没到齐！");
return;
}
System.out.println("Tom出发！！！");
}).start();
Thread.sleep(100);
