5 for(constauto&x:vec){
6 pq.push(x);
7 if(pq.size()>topK){
8 // 如果超出个数，则弹出堆顶（最小的）数据
9 pq.pop();
10 }
11 }
12
13 while(!pq.empty()){
14 cout<<pq.top()<<endl; // 输出依次为7,8,9
15 pq.pop();
16 }
17
