快排大家都知道，针对 topK 问题，可以对快排进行改进。仅对部分数据进行递归计
算。比如，在 100 个数字中，找最大的 10 个，第一次循环的时候，povit 被移动到
了 80 的位置，则接下来仅需要在后面的 20 个数字中找最大的 10 个即可。
这样做的优势是，理论最优时间复杂度可以达到 O(n)，不过平均时间复杂度还是
O(nlogn)。需要说明的是，通过这种方式，找出来的最大的 k 个数字之间，是无序的。
1 intpartition(vector<int>&arr,intbegin,intend){
2 intleft=begin;
3 intright=end;
4 intpovit=arr[begin];
5
6 while(left<right){
7 while(left<right&&arr[right]>=povit){right--;}
8 while(left<right&&arr[left]<=povit){left++;}

9 if(left<right){swap(arr[left],arr[right]);}
10 }
11
12 swap(arr[begin],arr[left]);
13 returnleft;
14 }
15
16 voidpartSort(vector<int>&arr,intbegin,intend,inttarget){
17 if(begin>=end){
18 return;
19 }
20
21 intpovit=partition(arr,begin,end);
22 if(target<povit){
23 partSort(arr,begin,povit-1,target);
24 }elseif(target>povit){
25 partSort(arr,povit+1,end,target);
26 }
27 }
28
29 vector<int>getMaxNumbers(vector<int>&arr,intk){
30 intsize=(int)arr.size();
31 // 把求最大的k个数，转换成求最小的size-k个数字
32 inttarget=size-k;
33 partSort(arr,0,size-1,target);
34 vector<int>ret(arr.end()-k,arr.end());
35 returnret;
36 }
